{
    "name": "laravel/boost",
    "description": "Laravel Boost accelerates AI-assisted development by providing the essential context and structure that AI needs to generate high-quality, Laravel-specific code.",
    "keywords": [
        "dev",
        "laravel",
        "ai"
    ],
    "homepage": "https://github.com/laravel/boost",
    "license": "MIT",
    "support": {
        "issues": "https://github.com/laravel/boost/issues",
        "source": "https://github.com/laravel/boost"
    },
    "require": {
        "php": "^8.0",
        "guzzlehttp/guzzle": "^7.2",
        "illuminate/console": "^8.0|^9.0|^10.0|^11.0|^12.0",
        "illuminate/contracts": "^8.0|^9.0|^10.0|^11.0|^12.0",
        "illuminate/routing": "^8.0|^9.0|^10.0|^11.0|^12.0",
        "illuminate/support": "^8.0|^9.0|^10.0|^11.0|^12.0",
        "laravel/mcp": "^0.5.1",
        "laravel/prompts": "^0.3.0",
        "laravel/roster": "^0.2.9"
    },
    "require-dev": {
        "laravel/pint": "^1.0",
        "mockery/mockery": "^1.4.4",
        "orchestra/testbench": "^6.0|^7.0|^8.0|^9.0|^10.0",
        "pestphp/pest": "^1.0|^2.0|^3.0|^4.0",
        "phpstan/phpstan": "^1.0|^2.0",
        "rector/rector": "^1.0|^2.0"
    },
    "autoload": {
        "psr-4": {
            "Laravel\\Boost\\": "src/"
        }
    },
    "autoload-dev": {
        "psr-4": {
            "Tests\\": "tests/"
        }
    },
    "extra": {
        "branch-alias": {
            "dev-master": "1.x-dev"
        },
        "laravel": {
            "providers": [
                "Laravel\\Boost\\BoostServiceProvider"
            ]
        }
    },
    "scripts": {
        "lint": [
            "pint --format agent",
            "phpstan --memory-limit=-1",
            "rector"
        ],
        "test": "pest",
        "test:lint": [
            "pint --test --format agent",
            "rector --dry-run"
        ],
        "test:types": "phpstan",
        "check": [
            "@composer lint",
            "@composer test"
        ]
    },
    "config": {
        "sort-packages": true,
        "allow-plugins": {
            "pestphp/pest-plugin": true
        }
    },
    "minimum-stability": "dev",
    "prefer-stable": true
}

